<!--
 * 退订记录管理页面
 *
 * <p>退订记录管理，支持分页查询退订记录、恢复订阅操作。
 *
 * @path apps/message-web/src/views/unsubscribe-records/index.vue
 * @author ydsz-team
 * @since 1.0.0
-->
<script lang="ts" setup>
/**
 * 退订记录管理（列表页）
 * <p>消费后端契约 UnsubscribeController（src/api/unsubscribe.ts，auto-generated by bash/gen-contract.py）：
 * page({query: UnsubscribeQueryDTO}) 分页查询退订记录；行操作「恢复订阅」调 resubscribe({userId, topicCode, channel})。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import type { VxeTableGridOptions } from '@ydsz/plugins/vxe-table';

import { Page } from '@ydsz/common-ui';

import { h } from 'vue';

import { Badge, Button } from '@ydsz-core/ui-kit/shadcn-ui';

import { useYDSZVxeGrid } from '#/adapter/vxe-table';
import { page, resubscribe } from '#/api/unsubscribe';
import type { MsgSubscriptionVO } from '#/api/models';

defineOptions({ name: 'UnsubscribeRecordManagement' });

/** 状态列 Tag 类型映射 */
function mapTagVariant(type: 'success' | 'danger' | 'warning' | 'info'): 'default' | 'destructive' | 'outline' | 'secondary' {
  if (type === 'danger') return 'destructive';
  if (type === 'warning') return 'outline';
  if (type === 'info') return 'secondary';
  return 'default';
}

function getStatusType(status?: string): 'success' | 'danger' | 'warning' | 'info' {
  const upper = (status ?? '').toUpperCase();
  if (['SUBSCRIBED', 'ACTIVE'].includes(upper)) return 'success';
  if (['UNSUBSCRIBED'].includes(upper)) return 'danger';
  return 'info';
}

const gridOptions: VxeTableGridOptions<MsgSubscriptionVO> = {
  columns: [
    { type: 'seq', width: 50, title: '序号' },
    { field: 'id', title: '记录ID', width: 200 },
    { field: 'userId', title: '用户ID', width: 160 },
    { field: 'topicCode', title: '主题编码', width: 140 },
    { field: 'channel', title: '通道', width: 100 },
    {
      field: 'status',
      title: '状态',
      width: 110,
      slots: {
        default: ({ row }) =>
          h(Badge, { variant: mapTagVariant(getStatusType(row.status)) }, () => row.status ?? '-'),
      },
    },
    { field: 'roleScope', title: '角色范围', width: 120 },
    { field: 'unsubscribedAt', title: '退订时间', width: 170 },
    { field: 'createdAt', title: '创建时间', width: 170 },
    {
      field: 'action',
      title: '操作',
      width: 110,
      fixed: 'right',
      slots: {
        default: ({ row }) =>
          h(
            Button,
            {
              size: 'sm',
              variant: 'link',
              disabled: row.status === 'SUBSCRIBED',
              onClick: () => handleResubscribe(row),
            },
            () => '恢复订阅',
          ),
      },
    },
  ],
  height: 'auto',
  pagerConfig: { pageSize: 20, pageSizes: [10, 20, 50, 100] },
  proxyConfig: {
    ajax: {
      query: async (_page, formValues) => {
        const res = await page({ query: { ...formValues } });
        return { items: res.data ?? [], total: res.total ?? 0 };
      },
    },
  },
  toolbarConfig: { custom: true, refresh: { code: 'query' }, search: true, zoom: true },
  formConfig: {
    enabled: true,
    items: [
      {
        field: 'userId',
        title: '用户ID',
        itemRender: { name: 'Input', props: { placeholder: '用户ID' } },
      },
      {
        field: 'topicCode',
        title: '主题编码',
        itemRender: { name: 'Input', props: { placeholder: '主题编码' } },
      },
      {
        field: 'channel',
        title: '通道',
        itemRender: { name: 'Input', props: { placeholder: '通道' } },
      },
    ],
  },
};

const [Grid, gridApi] = useYDSZVxeGrid({ gridOptions });

/** 恢复订阅 */
async function handleResubscribe(row: MsgSubscriptionVO) {
  if (!row.userId || !row.topicCode || !row.channel) return;
  // 步骤1：确认弹窗（用户取消直接返回）
  try {
    await ydszConfirm(
      `确定恢复用户「${row.userId}」对主题「${row.topicCode}」的订阅吗？`,
      '恢复订阅确认',
      { type: 'warning' },
    );
  } catch {
    return; // 用户主动取消操作
  }
  // 步骤2：执行恢复订阅 API（失败提示由 errorMessageResponseInterceptor 统一处理）
  try {
    await resubscribe({ userId: row.userId, topicCode: row.topicCode, channel: row.channel });
    showToast.success('恢复订阅成功');
    gridApi.query();
  } catch {
    // 错误已由请求拦截器展示，无需重复处理
  }
}
</script>
<template>
  <Page auto-content-height>
    <Grid table-title="退订记录" />
  </Page>
</template>
